import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"HardwarePT — Hardware Pentest Toolkit","description":"A low-level hardware probing and penetration-testing toolkit written in C — ports, devices, firmware surfaces and stress probes.","frontmatter":{"title":"HardwarePT — Hardware Pentest Toolkit","description":"A low-level hardware probing and penetration-testing toolkit written in C — ports, devices, firmware surfaces and stress probes."},"headers":[],"relativePath":"en/projects/hardwarept/index.md","filePath":"en/projects/hardwarept/index.md"}`),a={name:`en/projects/hardwarept/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hardwarept-—-hardware-pentest-toolkit" tabindex="-1">HardwarePT — Hardware Pentest Toolkit <a class="header-anchor" href="#hardwarept-—-hardware-pentest-toolkit" aria-label="Permalink to “HardwarePT — Hardware Pentest Toolkit”">​</a></h1><p><strong><a href="https://github.com/Godde3s/HardwarePT" target="_blank" rel="noreferrer">HardwarePT</a></strong> is my low-level C project: a hardware-focused probing and pentest toolkit that talks to the machine underneath the operating system. It grew out of the same curiosity that pulled me into industrial automation — wanting to know what a device does <em>before</em> trusting what it claims.</p><h2 id="what-it-covers" tabindex="-1">What it covers <a class="header-anchor" href="#what-it-covers" aria-label="Permalink to “What it covers”">​</a></h2><ul><li><strong>Hardware enumeration</strong> — buses, devices and interfaces surfaced from user space.</li><li><strong>Attack-surface probing</strong> — exposed debug interfaces, weak default configurations and unsafe device states.</li><li><strong>Stress probes</strong> — controlled load generation to watch how hardware and firmware behave at the edges.</li><li><strong>Pure C, no frameworks</strong> — direct syscalls and interfaces, the kind of code that teaches you what your tooling actually does.</li></ul><p>It sits in the security lane of my portfolio next to my static-analysis and bug-hunting tools: understanding systems by taking them apart — hardware this time — and writing down what I find in reusable form. For a software engineer, there is no better debug lesson than watching a board misbehave because you assumed the timing was somebody else&#39;s problem.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};